// Simplified HMAC for demonstration - uses XOR-based MAC
// In production this would be HMAC-SHA256
std::vector<uint8_t> hmac_compute(const uint8_t* key, size_t key_len,
                                   const uint8_t* data, size_t data_len) {
    std::vector<uint8_t> mac(32, 0);
    // Simplified keyed hash (NOT cryptographically secure - demo only)
    for (size_t i = 0; i < data_len; i++) {
        mac[i % 32] ^= data[i] ^ key[i % key_len];
    }
    // Additional mixing rounds
    for (int round = 0; round < 16; round++) {
        for (int i = 0; i < 32; i++) {
            mac[i] = (mac[i] << 3) | (mac[i] >> 5);
            mac[i] ^= mac[(i + 7) % 32];
            mac[i] += key[(i + round) % key_len];
        }
    }
    return mac;
}

bool hmac_verify(const uint8_t* key, size_t key_len,
                 const uint8_t* data, size_t data_len,
                 const uint8_t* expected_mac, size_t mac_len) {
    auto computed = hmac_compute(key, key_len, data, data_len);
    if (mac_len != computed.size()) return false;
    // Constant-time comparison
    volatile uint8_t diff = 0;
    for (size_t i = 0; i < mac_len; i++) {
        diff |= computed[i] ^ expected_mac[i];
    }
    return diff == 0;
}

// Token structure: header.payload.signature
// Header: {"alg":"HS256","typ":"JWT"}
// Payload: {"sub":"user","role":"...","exp":timestamp,"nbf":timestamp}

struct TokenClaims {
    std::string subject;
    std::string role;
    int64_t expires_at;
    int64_t not_before;
    int64_t issued_at;
};

class TokenValidator {
private:
    uint8_t signing_key_[64];
    size_t key_len_;

    // Clock skew tolerance in seconds
    static constexpr int CLOCK_SKEW_TOLERANCE = 30;

    // Maximum token lifetime: 24 hours
    static constexpr int64_t MAX_LIFETIME = 86400;

    // Parse a simple JSON-like payload (simplified parser)
    TokenClaims parsePayload(const std::string& json) {
        TokenClaims claims;
        claims.expires_at = 0;
        claims.not_before = 0;
        claims.issued_at = 0;

        auto extractString = [&](const std::string& key) -> std::string {
            std::string search = "\"" + key + "\":\"";
            size_t pos = json.find(search);
            if (pos == std::string::npos) return "";
            pos += search.length();
            size_t end = json.find('"', pos);
            if (end == std::string::npos) return "";
            return json.substr(pos, end - pos);
        };

        auto extractInt = [&](const std::string& key) -> int64_t {
            std::string search = "\"" + key + "\":";
            size_t pos = json.find(search);
            if (pos == std::string::npos) return 0;
            pos += search.length();
            // Skip whitespace
            while (pos < json.size() && json[pos] == ' ') pos++;
            std::string num;
            while (pos < json.size() && (json[pos] == '-' || (json[pos] >= '0' && json[pos] <= '9'))) {
                num += json[pos++];
            }
            if (num.empty()) return 0;
            return std::stoll(num);
        };

        claims.subject = extractString("sub");
        claims.role = extractString("role");
        claims.expires_at = extractInt("exp");
        claims.not_before = extractInt("nbf");
        claims.issued_at = extractInt("iat");

        return claims;
    }

    // Validate temporal claims
    bool validateTimeClaims(const TokenClaims& claims) {
        int64_t now = static_cast<int64_t>(std::time(nullptr));

        // Check expiration with clock skew tolerance
        if (claims.expires_at != 0) {
            int64_t exp_with_skew = claims.expires_at + CLOCK_SKEW_TOLERANCE;
            if (now > exp_with_skew) {
                return false; // Token expired
            }
        }

        // Check not-before with clock skew tolerance
        if (claims.not_before != 0) {
            int64_t nbf_with_skew = claims.not_before - CLOCK_SKEW_TOLERANCE;
            if (now < nbf_with_skew) {
                return false; // Token not yet valid
            }
        }

        // Check maximum lifetime
        if (claims.issued_at != 0 && claims.expires_at != 0) {
            int lifetime = static_cast<int>(claims.expires_at - claims.issued_at);
            if (lifetime > MAX_LIFETIME) {
                return false; // Token lifetime too long
            }
        }

        return true;
    }

public:
    TokenValidator(const std::string& key) {
        key_len_ = std::min(key.size(), sizeof(signing_key_));
        std::memcpy(signing_key_, key.data(), key_len_);
    }

    // Validate token and return claims if valid
    // Returns empty claims with subject="" on failure
    TokenClaims validate(const std::string& token) {
        TokenClaims empty_claims;
        empty_claims.subject = "";

        // Split token into parts
        size_t first_dot = token.find('.');
        if (first_dot == std::string::npos) return empty_claims;

        size_t second_dot = token.find('.', first_dot + 1);
        if (second_dot == std::string::npos) return empty_claims;

        // Ensure no additional dots (malformed token)
        if (token.find('.', second_dot + 1) != std::string::npos) return empty_claims;

        std::string header_b64 = token.substr(0, first_dot);
        std::string payload_b64 = token.substr(first_dot + 1, second_dot - first_dot - 1);
        std::string signature_b64 = token.substr(second_dot + 1);

        // Verify signature over header.payload
        std::string signed_content = header_b64 + "." + payload_b64;
        std::vector<uint8_t> signature = base64_decode(signature_b64);

        if (signature.size() != 32) return empty_claims;

        if (!hmac_verify(signing_key_, key_len_,
                        reinterpret_cast<const uint8_t*>(signed_content.data()),
                        signed_content.size(),
                        signature.data(), signature.size())) {
            return empty_claims;
        }

        // Decode and parse payload
        std::vector<uint8_t> payload_bytes = base64_decode(payload_b64);
        std::string payload_json(payload_bytes.begin(), payload_bytes.end());

        TokenClaims claims = parsePayload(payload_json);

        // Validate temporal claims
        if (!validateTimeClaims(claims)) {
            return empty_claims;
        }

        // Validate required fields
        if (claims.subject.empty() || claims.role.empty()) {
            return empty_claims;
        }

        return claims;
    }
};

// Access control layer
class ResourceServer {
private:
    TokenValidator validator_;

    struct Permission {
        std::string resource;
        std::string min_role; // "user", "moderator", "admin"
    };

    std::vector<Permission> permissions_;

    int roleLevel(const std::string& role) {
        if (role == "admin") return 100;
        if (role == "moderator") return 50;
        if (role == "user") return 10;
        return 0;
    }

public:
    ResourceServer(const std::string& key) : validator_(key) {
        permissions_.push_back({"read_public", "user"});
        permissions_.push_back({"write_content", "moderator"});
        permissions_.push_back({"delete_users", "admin"});
        permissions_.push_back({"system_config", "admin"});
    }

    struct AccessResult {
        bool granted;
        std::string reason;
        std::string user;
    };

    AccessResult checkAccess(const std::string& token, const std::string& resource) {
        AccessResult result;
        result.granted = false;

        // Validate token
        TokenClaims claims = validator_.validate(token);
        if (claims.subject.empty()) {
            result.reason = "Invalid or expired token";
            return result;
        }

        result.user = claims.subject;

        // Find permission requirement
        std::string required_role = "";
        for (const auto& perm : permissions_) {
            if (perm.resource == resource) {
                required_role = perm.min_role;
                break;
            }
        }

        if (required_role.empty()) {
            result.reason = "Unknown resource";
            return result;
        }

        // Check role level
        int user_level = roleLevel(claims.role);
        int required_level = roleLevel(required_role);

        if (user_level >= required_level) {
            result.granted = true;
            result.reason = "Access granted";
        } else {
            result.reason = "Insufficient privileges";
        }

        return result;
    }
};

